<?php $type=$_GET['type']??'blogs';$allowed=['blogs','events','testimonials','services'];if(!in_array($type,$allowed))$type='blogs';$admin_title=ucfirst($type);include '_header.php';$rows=$pdo->query("SELECT * FROM `$type` ORDER BY id DESC")->fetchAll();?><div class="panel"><div class="panel-head"><div><h2><?=e(ucfirst($type))?> Management</h2><small>Search, edit, publish and remove data-driven content.</small></div><a class="btn btn-primary" href="content_form.php?type=<?=urlencode($type)?>"><i class="fa-solid fa-plus"></i> Add <?=e(rtrim(ucfirst($type),'s'))?></a></div><div style="padding:15px"><input id="contentSearch" class="form-control" placeholder="Search <?=e($type)?>..."></div><div class="table-wrap"><table id="contentTable"><thead><tr><?php if($type==='blogs'):?><th>Cover</th><th>Category</th><?php endif;?><th>Subject / Title</th><?php if($type==='blogs'):?><th>Feedback</th><th>Published</th><?php else:?><th>Status</th><th>Created</th><?php endif;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($type==='blogs'):?><td><img src="../<?=e($r['image_url'])?>" style="width:70px;height:50px;object-fit:cover;border-radius:10px"></td><td><?=e($r['category']??'General')?></td><?php endif;?><td><b><?=e($r['title']??$r['name']??'Untitled')?></b></td><?php if($type==='blogs'):$q=$pdo->prepare("SELECT COUNT(*) FROM blog_comments WHERE blog_id=?");$q->execute([$r['id']]);$c=$q->fetchColumn();?><td><i class="fa-solid fa-comment"></i> <?=$c?></td><td><?=!empty($r['published_at'])?date('d M Y',strtotime($r['published_at'])):'Draft'?></td><?php else:?><td><span class="badge green"><?=e($r['status']??'published')?></span></td><td><?=isset($r['created_at'])?date('d M Y',strtotime($r['created_at'])):'—'?></td><?php endif;?><td><a class="btn" href="content_form.php?type=<?=urlencode($type)?>&id=<?=$r['id']?>"><i class="fa-solid fa-pen"></i></a> <button class="btn btn-danger" data-delete-url="api/delete_content.php?type=<?=urlencode($type)?>&id=<?=$r['id']?>"><i class="fa-solid fa-trash"></i></button></td></tr><?php endforeach;?></tbody></table></div></div><script>document.getElementById('contentSearch')?.addEventListener('input',e=>{document.querySelectorAll('#contentTable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(e.target.value.toLowerCase())?'':'none')});</script><?php include '_footer.php'; ?>